class Solution {
 int reverseNum(int x){int y=0;while(x){y=y*10+x%10;x/=10;}return y;}
public:
 int countNicePairs(vector<int>& nums){
  const int MOD=1000000007;unordered_map<int,int> cnt;long long ans=0;
  for(int x:nums){int d=x-reverseNum(x);ans=(ans+cnt[d])%MOD;++cnt[d];}
  return ans;
 }
};
